#!/usr/bin/env node
/**
 * Bundle analysis for the Expo web export (issue #38).
 *
 * Attributes every generated byte of a bundled chunk back to the source file it
 * came from, using the chunk's source map. This is the only way to know what is
 * actually *shipped*: file size on disk says nothing about bundle weight
 * (issue #45 removed 5933 lines of dead code for a 0 byte gain).
 *
 * Usage:
 *   npx expo export --platform web --source-maps --output-dir dist-map
 *   node scripts/analyze-bundle.js dist-map [--top 20] [--json out.json]
 */

const fs = require('fs');
const path = require('path');
const zlib = require('zlib');
const { SourceMapConsumer } = require('source-map');

function parseArgs(argv) {
  const args = { dir: 'dist-map', top: 20, json: null };
  const rest = [];
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--top') args.top = Number(argv[++i]);
    else if (argv[i] === '--json') args.json = argv[++i];
    else rest.push(argv[i]);
  }
  if (rest[0]) args.dir = rest[0];
  return args;
}

/** Collapse a source path into the "owner" we report on. */
function bucketOf(source) {
  const clean = source.replace(/\\/g, '/').replace(/^(\.\.\/)+/, '');
  const nm = clean.lastIndexOf('node_modules/');
  if (nm !== -1) {
    const after = clean.slice(nm + 'node_modules/'.length);
    const parts = after.split('/');
    const pkg = parts[0].startsWith('@') ? `${parts[0]}/${parts[1]}` : parts[0];
    return { bucket: `node_modules/${pkg}`, kind: 'dependency', file: clean };
  }
  return { bucket: clean, kind: 'app', file: clean };
}

async function analyzeChunk(jsPath) {
  const code = fs.readFileSync(jsPath, 'utf8');
  const mapPath = `${jsPath}.map`;
  if (!fs.existsSync(mapPath)) return null;
  const map = JSON.parse(fs.readFileSync(mapPath, 'utf8'));

  const lines = code.split('\n');
  const lineOffsets = [];
  let off = 0;
  for (const l of lines) {
    lineOffsets.push(off);
    off += l.length + 1;
  }

  const bySource = new Map();
  const byLine = lines.map(() => new Map()); // per-line: source -> bytes
  let unattributed = 0;

  // source-map@0.6 normalizes source URLs (it turns Metro's `\0polyfill:...`
  // pseudo-sources into "."), which would silently merge unrelated modules into
  // one bucket. Feed it opaque indices instead and map them back ourselves.
  const originalSources = map.sources.slice();
  const consumer = new SourceMapConsumer({
    ...map,
    sourceRoot: undefined,
    sources: originalSources.map((_, i) => `srcidx${i}`),
  });
  const resolveSource = (s) => {
    const m = /^srcidx(\d+)$/.exec(s || '');
    return m ? originalSources[Number(m[1])] : s;
  };

  // Collect all mappings, ordered by generated position; each mapping owns the
  // bytes from its start up to the start of the next mapping.
  const mappings = [];
  consumer.eachMapping((m) => {
    mappings.push({
      line: m.generatedLine,
      col: m.generatedColumn,
      source: resolveSource(m.source),
    });
  });
  mappings.sort((a, b) => (a.line - b.line) || (a.col - b.col));

  const posOf = (line, col) => (lineOffsets[line - 1] ?? code.length) + col;

  for (let i = 0; i < mappings.length; i++) {
    const start = posOf(mappings[i].line, mappings[i].col);
    const end = i + 1 < mappings.length
      ? posOf(mappings[i + 1].line, mappings[i + 1].col)
      : code.length;
    const size = Math.max(0, end - start);
    if (i === 0 && start > 0) unattributed += start;
    const src = mappings[i].source;
    // source-map@0.6 reports mappings with no original source as ".": these are
    // the Metro module wrappers (`__d(function(g,r,i,a,m,e,d){...}, id, [deps])`)
    // and the require runtime, i.e. per-module bundler overhead.
    if (!src || src === '.') {
      unattributed += size;
      continue;
    }
    bySource.set(src, (bySource.get(src) || 0) + size);
    const ln = byLine[mappings[i].line - 1];
    if (ln) ln.set(src, (ln.get(src) || 0) + size);
  }

  // Metro emits one `__d(factory, id, [deps])` per line. Minified code loses a
  // lot of mappings, so per-mapping attribution alone under-counts by ~20%.
  // Assigning each whole line to the source that owns most of its mapped bytes
  // attributes 100% of the chunk and is what the report below uses.
  const byModule = new Map();
  let unassignedLines = 0;
  lines.forEach((line, idx) => {
    const bytes = line.length + 1;
    const ln = byLine[idx];
    let best = null;
    let bestSize = 0;
    for (const [src, size] of ln) {
      if (size > bestSize) { best = src; bestSize = size; }
    }
    if (!best) { unassignedLines += bytes; return; }
    byModule.set(best, (byModule.get(best) || 0) + bytes);
  });
  if (typeof consumer.destroy === 'function') consumer.destroy();

  return { code, bySource: byModule, unattributed: unassignedLines, perMapping: bySource };

}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const webDir = path.join(args.dir, '_expo/static/js/web');
  if (!fs.existsSync(webDir)) {
    console.error(`No bundle output at ${webDir}. Run: npx expo export --platform web --source-maps --output-dir ${args.dir}`);
    process.exit(1);
  }

  const entryFile = fs.readdirSync(webDir).find((f) => f.startsWith('entry-') && f.endsWith('.js'));
  if (!entryFile) {
    console.error('No entry-*.js chunk found.');
    process.exit(1);
  }
  const entryPath = path.join(webDir, entryFile);

  const result = await analyzeChunk(entryPath);
  if (!result) {
    console.error(`No source map next to ${entryFile}. Re-export with --source-maps.`);
    process.exit(1);
  }

  const raw = Buffer.byteLength(result.code);
  const br = zlib.brotliCompressSync(Buffer.from(result.code), {
    params: { [zlib.constants.BROTLI_PARAM_QUALITY]: 11 },
  }).length;
  const gz = zlib.gzipSync(Buffer.from(result.code), { level: 9 }).length;

  // Aggregate per bucket (package or app file) and per top-level area.
  const buckets = new Map();
  const files = [];
  for (const [source, size] of result.bySource) {
    const { bucket, kind } = bucketOf(source);
    const cur = buckets.get(bucket) || { bucket, kind, size: 0, files: 0 };
    cur.size += size;
    cur.files += 1;
    buckets.set(bucket, cur);
    files.push({ file: source.replace(/\\/g, '/'), size });
  }

  const sorted = [...buckets.values()].sort((a, b) => b.size - a.size);
  files.sort((a, b) => b.size - a.size);

  const kb = (n) => (n / 1024).toFixed(1).padStart(8);
  const pct = (n) => `${((n / raw) * 100).toFixed(1)}%`.padStart(6);

  console.log(`\n=== Entry chunk: ${entryFile} ===`);
  console.log(`raw: ${raw} B (${(raw / 1024 / 1024).toFixed(2)} MB)`);
  console.log(`brotli(q11): ${br} B (${(br / 1024).toFixed(1)} KB)`);
  console.log(`gzip(9): ${gz} B (${(gz / 1024).toFixed(1)} KB)`);
  console.log(`attributed to sources: ${raw - result.unattributed} B, unattributed (runtime/glue): ${result.unattributed} B`);

  console.log(`\n--- Top ${args.top} contributors (package / app file), raw bytes ---`);
  console.log('   rank        KB       %  kind        name');
  sorted.slice(0, args.top).forEach((b, i) => {
    console.log(`   ${String(i + 1).padStart(4)}  ${kb(b.size)}  ${pct(b.size)}  ${b.kind.padEnd(10)}  ${b.bucket}  (${b.files} files)`);
  });

  console.log(`\n--- Top ${args.top} individual source files ---`);
  files.slice(0, args.top).forEach((f, i) => {
    console.log(`   ${String(i + 1).padStart(4)}  ${kb(f.size)}  ${pct(f.size)}  ${f.file}`);
  });

  const depTotal = sorted.filter((b) => b.kind === 'dependency').reduce((s, b) => s + b.size, 0);
  const appTotal = sorted.filter((b) => b.kind === 'app').reduce((s, b) => s + b.size, 0);
  console.log(`\n--- Split ---`);
  console.log(`   dependencies: ${kb(depTotal)} KB (${pct(depTotal)})`);
  console.log(`   app code    : ${kb(appTotal)} KB (${pct(appTotal)})`);

  if (args.json) {
    fs.writeFileSync(
      args.json,
      JSON.stringify({ entryFile, raw, brotli: br, gzip: gz, buckets: sorted, files: files.slice(0, 200) }, null, 2)
    );
    console.log(`\nJSON written to ${args.json}`);
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
